CREATE TABLE IF NOT EXISTS evidence(
  namespace TEXT,key TEXT,body TEXT,provenance TEXT,created REAL,
  PRIMARY KEY(namespace,key));

CREATE TABLE IF NOT EXISTS observations(
  candidate TEXT NOT NULL,observation TEXT NOT NULL,body TEXT NOT NULL,at REAL NOT NULL,
  PRIMARY KEY(candidate,observation));

CREATE TABLE IF NOT EXISTS pons_current_watch(
  candidate TEXT PRIMARY KEY,body TEXT NOT NULL,hash TEXT NOT NULL,
  next_at REAL NOT NULL,attempt INTEGER NOT NULL DEFAULT ?);

CREATE TABLE IF NOT EXISTS receipt_obligations(
  namespace TEXT,key TEXT,consumer TEXT,owner TEXT,generation TEXT,
  PRIMARY KEY(namespace,key,consumer,owner,generation),
  FOREIGN KEY(namespace,key) REFERENCES evidence(namespace,key) ON DELETE CASCADE);

CREATE TABLE IF NOT EXISTS rolling(
  candidate TEXT,identity TEXT,at INTEGER,block INTEGER,body TEXT,provenance TEXT,
  PRIMARY KEY(candidate,identity));

CREATE TABLE IF NOT EXISTS transitions(
  seq INTEGER PRIMARY KEY,candidate TEXT,generation INTEGER,at REAL,kind TEXT,
  reason TEXT,watermark TEXT,interpretation TEXT,details TEXT);

CREATE TRIGGER IF NOT EXISTS candidate_protection_revision_delete
      BEFORE DELETE ON candidate_protection_revision
      BEGIN SELECT RAISE(ABORT,?); END;
